from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
s = json.loads((ROOT / "spec/registers.json").read_text())

h = [
	"/* Generated by scripts/gen_spec.py. */",
	"#ifndef DET_SPEC_H",
	"#define DET_SPEC_H",
	"",
	f"#define DET_BASE 0x{s['base']:08x}u",
	f"#define DET_VERSION 0x{s['version']:08x}u",
	"",
]
v = [
	"// Generated by scripts/gen_spec.py.",
	"",
	f"\tlocalparam [31:0] DET_INTERFACE_VERSION = 32'h{s['version']:08x};",
	"",
]

for k, val in s["registers"].items():
	h.append(f"#define DET_REG_{k} {val}u")
	v.append(f"\tlocalparam [7:0] REG_{k} = 8'd{val};")

for key, pre in [("descriptor", "D"), ("fusion", "F")]:
	h.append("")
	v.append("")

	for i, k in enumerate(s[key]):
		if k.startswith("RESERVED") and k != "RESERVED":
			continue

		h.append(f"#define {pre}_{k} {i}u")
		v.append(f"\tlocalparam integer {pre}_{k} = {i};")

h += ["", f"#define POOL_BASE 0x{s['pool_base']:08x}u"]
pool_v = ["// Generated by scripts/gen_spec.py."]
for key, val in s["pool_registers"].items():
	h.append(f"#define POOL_REG_{key} {val}u")
	pool_v.append(f"\tlocalparam [7:0] POOL_REG_{key} = 8'd{val};")
(ROOT / "rtl/pool_spec.vh").write_text("\n".join(pool_v) + "\n")
h += ["", "#endif", ""]

(ROOT / "firmware/spec.h").write_text("\n".join(h))
(ROOT / "rtl/spec.vh").write_text("\n".join(v) + "\n")
